          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "generatedEvent",
    "test"
  ],
  "propertyOrdering": [
    "generatedEvent",
    "test"
  ]
