responseSchemaParserJs:
try {
    const parts = responseJson?.candidates?.[0]?.content?.parts;
    if (!parts || !Array.isArray(parts) || parts.length === 0) {
        return { error: 'No content parts found in response' };
    }

    const potentialDataSource = parts[0];
    let rawText = '';
    if (typeof potentialDataSource === 'object' && potentialDataSource !== null && typeof potentialDataSource.text === 'string') {
        rawText = potentialDataSource.text;
    } else if (typeof potentialDataSource === 'string') {
        rawText = potentialDataSource;
    } else {
        return { error: 'Response data part is not a string or object with text.', rawData: potentialDataSource };
    }

    let jsonString = '';
    const firstBraceIndex = rawText.indexOf('{');
    const lastBraceIndex = rawText.lastIndexOf('}');

    if (firstBraceIndex !== -1 && lastBraceIndex !== -1 && lastBraceIndex > firstBraceIndex) {
        jsonString = rawText.substring(firstBraceIndex, lastBraceIndex + 1);
    } else {
        return { error: 'Could not find valid JSON braces {} in raw text.', rawText: rawText };
    }

    let data;
    try {
        data = JSON.parse(jsonString);
    } catch (e) {
        return { error: `Failed to parse extracted JSON: ${e.message}`, rawText: rawText, extractedJson: jsonString };
    }

    if (!data || typeof data !== 'object' || !data.generatedEvent) {
        return { error: 'Parsed data is not a valid object or missing generatedEvent module.' };
    }

    const eventData = data.generatedEvent.eventRecord;
    const entryDetail = eventData?.entryDetail;
    const actions = [];

    if (entryDetail && typeof entryDetail === 'object') {
        const summary = (entryDetail.summary || '').trim();
        const details = (entryDetail.details || '').trim();

        if (summary) {
            let content = `【事件记录】\n摘要: ${summary}`;
            if (details) {
                content += `\n细节:\n${details}`;
            }
            actions.push({ type: 'description', content: content });
        }
    }

    return { 
        processedTurnActions: actions, 
        originalData: data
    };

} catch (e) {
    console.error("[plotSummaryMaster] Parser Exception:", e);
    return { error: `Parser exception: ${e.message}`, stack: e.stack };
}

